<script setup>
import { onMounted, reactive, ref } from 'vue';
import { Camera, KeyRound, LogOut, Monitor, Save, ShieldCheck, UserRound } from 'lucide-vue-next';
import api, { apiError } from '../services/api';
import { formatDateTime, timezoneFor } from '../utils/datetime';
import { useAuthStore } from '../stores/auth';
const auth = useAuthStore(); const timezone = timezoneFor(auth.user); const profile = reactive({ name: '', phone: '', avatar: null }); const password = reactive({ current_password: '', password: '', password_confirmation: '' }); const sessions = ref([]); const error = ref(''); const notice = ref('');
const load = async () => { try { profile.name = auth.user?.name || ''; profile.phone = auth.user?.phone || ''; sessions.value = (await api.get('/auth/sessions')).data.data; } catch (e) { error.value = apiError(e); } };
const saveProfile = async () => { error.value = ''; try { const body = new FormData(); body.append('name', profile.name); body.append('phone', profile.phone || ''); if (profile.avatar) body.append('avatar', profile.avatar); const data = (await api.post('/auth/profile', body)).data; auth.updateUser(data.user); notice.value = 'Profile updated.'; } catch (e) { error.value = apiError(e); } };
const changePassword = async () => { error.value = ''; try { await api.post('/auth/change-password', password); password.current_password = ''; password.password = ''; password.password_confirmation = ''; notice.value = 'Password changed.'; } catch (e) { error.value = apiError(e); } };
const revoke = async (session) => { if (session.current) return; await api.delete(`/auth/sessions/${session.id}`); await load(); }; onMounted(load);
</script>
<template><div class="mx-auto max-w-5xl space-y-5 fade-up"><div><p class="eyebrow flex items-center gap-2"><UserRound :size="13" /> Personal workspace</p><h1 class="mt-2 text-3xl font-semibold">Profile & sessions</h1><p class="mt-1 text-sm text-[#86ada3]">Manage your identity, password, and active devices.</p></div><p v-if="error" class="rounded-xl bg-rose-400/10 px-4 py-3 text-sm text-rose-200">{{ error }}</p><p v-if="notice" class="rounded-xl bg-emerald-300/10 px-4 py-3 text-sm text-emerald-100">{{ notice }}</p><div class="grid gap-5 lg:grid-cols-2"><section class="panel p-5 sm:p-6"><div class="flex items-center gap-4"><div class="relative flex h-16 w-16 items-center justify-center rounded-2xl bg-gradient-to-br from-emerald-200 to-cyan-300 text-xl font-bold text-[#062421]">{{ (profile.name || 'H').slice(0, 1) }}<label class="absolute -bottom-1 -right-1 flex h-7 w-7 cursor-pointer items-center justify-center rounded-lg border-2 border-[#082421] bg-emerald-300 text-[#062421]"><Camera :size="13"/><input @change="profile.avatar = $event.target.files?.[0]" type="file" accept="image/*" class="hidden"/></label></div><div><h2 class="font-semibold">{{ auth.user?.name }}</h2><p class="text-xs text-[#719b8e]">{{ auth.user?.email }}</p><span class="badge badge-green mt-2 capitalize">{{ auth.user?.roles?.[0]?.replace('-', ' ') }}</span></div></div><div class="mt-6 space-y-4"><div><label class="label">Full name</label><input v-model="profile.name" class="field" /></div><div><label class="label">Mobile</label><input v-model="profile.phone" class="field" /></div><button class="btn-primary" @click="saveProfile"><Save :size="15" /> Save profile</button></div></section><section class="panel p-5 sm:p-6"><div class="flex items-center gap-3"><span class="flex h-10 w-10 items-center justify-center rounded-xl bg-amber-300/10 text-amber-200"><KeyRound :size="18" /></span><div><h2 class="font-semibold">Change password</h2><p class="text-xs text-[#719b8e]">Use at least eight characters.</p></div></div><form class="mt-6 space-y-4" @submit.prevent="changePassword"><div><label class="label">Current password</label><input v-model="password.current_password" type="password" class="field" required /></div><div><label class="label">New password</label><input v-model="password.password" type="password" class="field" minlength="8" required /></div><div><label class="label">Confirm new password</label><input v-model="password.password_confirmation" type="password" class="field" minlength="8" required /></div><button class="btn-primary"><ShieldCheck :size="15" /> Update password</button></form></section></div><section class="panel overflow-hidden"><div class="flex items-center gap-3 border-b border-emerald-100/10 px-5 py-4"><Monitor :size="17" class="text-emerald-200"/><div><h2 class="font-semibold">Active sessions</h2><p class="text-xs text-[#719b8e]">Revoke other devices that have access to your account.</p></div></div><div class="divide-y divide-emerald-100/8"><div v-for="session in sessions" :key="session.id" class="flex items-center gap-3 px-5 py-4"><span class="flex h-9 w-9 items-center justify-center rounded-xl bg-emerald-300/10 text-emerald-200"><Monitor :size="16" /></span><div class="min-w-0 flex-1"><p class="text-sm text-white">{{ session.name }} <span v-if="session.current" class="badge badge-green ml-2">This device</span></p><p class="mt-1 text-xs text-[#719b8e]">Last used {{ formatDateTime(session.last_used_at, timezone) }}</p></div><button v-if="!session.current" class="btn-secondary px-3 py-2 text-xs" @click="revoke(session)"><LogOut :size="13" /> Revoke</button></div></div></section></div></template>
